// Generated by test-gen (standard) from docs/implementations/011-2026-07-13-post-trade-allocation-fe.md §FE-4.
// Regenerate: /test-gen standard.
import { describe, expect, it } from "vitest";
import { mapDtoToPostTradeAllocation, mapDtoToRuns, ptaMoney } from "@/lib/mobo/allocation";
import type { PtaRunsDTO, PtaViewDTO } from "@/lib/mobo/types";

const DTO: PtaViewDTO = {
  tradeDate: "2026-06-03",
  settleDay: "Tue 03 Jun 2026",
  grandTotal: 11_450_000, // deliberately NOT equal to the sum of model.traded below
  models: [
    {
      id: "9f2c",
      name: "Zero",
      acct: "U-1234567",
      traded: 6_800_000,
      unitsTotal: 25,
      clientShares: [
        { clientId: "3a11", name: "Strathmore Fund", units: 5, allocated: 1_360_000, pct: 20 },
        { clientId: "4b22", name: "Anchor Capital", units: 20, allocated: 5_440_000, pct: 80 },
      ],
    },
    {
      id: "a1b2",
      name: "Meridian",
      acct: "—",
      traded: -250_000, // a losing day — signed, must pass through unchanged
      unitsTotal: 10,
      clientShares: [
        { clientId: "3a11", name: "Strathmore Fund", units: 10, allocated: -250_000, pct: 100 },
      ],
    },
    {
      id: "c3d4",
      name: "Unsubscribed",
      acct: "U-9999999",
      traded: 0,
      unitsTotal: 0,
      clientShares: [],
    },
  ],
};

describe("FE-4 mapDtoToPostTradeAllocation", () => {
  it("passes every numeric/string field through unchanged — no derivation, no re-summation", () => {
    const view = mapDtoToPostTradeAllocation(DTO);
    expect(view.settleDay).toBe(DTO.settleDay);
    expect(view.grandTotal).toBe(DTO.grandTotal);
    expect(view.models).toHaveLength(3);
    view.models.forEach((m, i) => {
      const src = DTO.models[i];
      expect(m.id).toBe(src.id);
      expect(m.name).toBe(src.name);
      expect(m.acct).toBe(src.acct);
      expect(m.traded).toBe(src.traded);
      expect(m.unitsTotal).toBe(src.unitsTotal);
      expect(m.clientShares).toEqual(src.clientShares);
    });
  });

  it("carries a negative traded/allocated pair through unchanged (signed money)", () => {
    const view = mapDtoToPostTradeAllocation(DTO);
    const losingModel = view.models.find((m) => m.id === "a1b2")!;
    expect(losingModel.traded).toBe(-250_000);
    expect(losingModel.clientShares[0].allocated).toBe(-250_000);
  });

  it("maps a model with an empty clientShares array to an empty array, not an error", () => {
    const view = mapDtoToPostTradeAllocation(DTO);
    const unsubscribed = view.models.find((m) => m.id === "c3d4")!;
    expect(unsubscribed.clientShares).toEqual([]);
  });

  it("returns grandTotal verbatim from the DTO, never a re-derived sum of model.traded", () => {
    const view = mapDtoToPostTradeAllocation(DTO);
    const sumOfTraded = DTO.models.reduce((n, m) => n + m.traded, 0);
    expect(sumOfTraded).not.toBe(DTO.grandTotal);
    expect(view.grandTotal).toBe(DTO.grandTotal);
  });

  it("is deterministic — calling twice on the same DTO yields equal output", () => {
    expect(mapDtoToPostTradeAllocation(DTO)).toEqual(mapDtoToPostTradeAllocation(DTO));
  });
});

describe("FE-4 mapDtoToRuns", () => {
  const RUNS_DTO: PtaRunsDTO = {
    runs: [
      { date: "2026-06-03", label: "Tue 03 Jun 2026", grandTotal: 11_450_000 },
      { date: "2026-06-02", label: "Mon 02 Jun 2026", grandTotal: 0 },
    ],
  };

  it("maps runs[] 1:1", () => {
    expect(mapDtoToRuns(RUNS_DTO)).toEqual(RUNS_DTO.runs);
  });

  it("maps an empty runs list to an empty array, not an error", () => {
    expect(mapDtoToRuns({ runs: [] })).toEqual([]);
  });
});

describe("FE-4 ptaMoney (colocated presentation formatter)", () => {
  it("formats amounts >= 1e6 as $X.XXM", () => {
    expect(ptaMoney(6_800_000)).toBe("$6.80M");
  });

  it("formats amounts < 1e6 as a rounded $Xk", () => {
    expect(ptaMoney(250_000)).toBe("$250k");
  });

  it("formats a negative amount without throwing (sign carried into the k-suffix form)", () => {
    expect(ptaMoney(-250_000)).toBe("$-250k");
  });

  it("formats amounts under 1e3 as a plain dollar amount, not $0k", () => {
    expect(ptaMoney(270)).toBe("$270");
    expect(ptaMoney(-50)).toBe("$-50");
  });
});
